<?php
require '_layout.php';
$kind=$_GET['kind']??'category'; $map=['category'=>['categories','Category','categories.php','category-form.php'],'collection'=>['collections','Collection','collections.php','collection-form.php']]; if(!isset($map[$kind])){http_response_code(404);exit;} [$table,$singular,$listPage,$formPage]=$map[$kind];
$pdo=db();$items=[];if($pdo)try{$items=$pdo->query("SELECT * FROM $table ORDER BY id DESC")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){} admin_header('Quản lý '.$singular,$kind==='category'?'categories':'collections'); admin_flash(); ?>
<section class="products-admin"><div class="dashboard-actions"><div><div class="kicker">Danh mục nội dung</div><h2>Quản lý <?=$singular?></h2><p>Thiết lập tên, mã, ảnh, hệ số và ghi chú cho <?=$kind==='category'?'nhóm sản phẩm':'bộ sưu tập sản phẩm'?>.</p></div><a class="admin-button" href="<?=$formPage?>">+ Thêm <?=$singular?></a></div><div class="toolbar"><label class="search"><span>⌕</span><input type="search" placeholder="Tìm theo tên hoặc mã..." data-taxonomy-search></label></div><?php if(!$pdo): ?><div class="notice error">MySQL chưa kết nối.</div><?php elseif(!$items): ?><div class="empty"><div>□</div><h3>Chưa có <?=$singular?></h3><p>Hãy tạo mục đầu tiên.</p><a class="admin-button" href="<?=$formPage?>">+ Thêm <?=$singular?></a></div><?php else: ?><div class="product-table taxonomy-table"><div class="table-row table-head"><span><?=$singular?></span><span>Mã</span><span>Hệ số</span><span>Ghi chú</span><span></span></div><?php foreach($items as $item): ?><article class="table-row" data-taxonomy-row data-search="<?=htmlspecialchars(mb_strtolower($item['name'].' '.$item['code']))?>"><div class="admin-product"><?php if($item['image']): ?><img src="<?=htmlspecialchars($item['image'])?>" alt=""><?php else: ?><span class="image-empty">□</span><?php endif ?><div><b><?=htmlspecialchars($item['name'])?></b><small>ID #<?=$item['id']?></small></div></div><code><?=htmlspecialchars($item['code'])?></code><strong>× <?=number_format((float)$item['coefficient'],2,',','.')?></strong><span class="notes-cell"><?=htmlspecialchars($item['notes']?:'—')?></span><div class="table-actions"><a href="<?=$formPage?>?id=<?=$item['id']?>">Sửa</a><form method="post" action="taxonomy-delete.php" onsubmit="return confirm('Xoá mục này?')"><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=$item['id']?>"><button>Xoá</button></form></div></article><?php endforeach ?></div><?php endif ?></section><?php admin_footer(); ?>
